#!/bin/bash
# Script to easily save the map generated by SLAM
MAP_NAME=${1:-"room_map"}
MAP_DIR="/home/alvaro/Desktop/TFM/xgo_sim/maps"

mkdir -p "$MAP_DIR"
echo "Saving SLAM map to: $MAP_DIR/$MAP_NAME"

ros2 run nav2_map_server map_saver_cli -f "$MAP_DIR/$MAP_NAME" --ros-args -p use_sim_time:=true

echo "Done! Saved $MAP_DIR/$MAP_NAME.yaml and $MAP_DIR/$MAP_NAME.pgm"
